CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), username text UNIQUE NOT NULL, password_hash text NOT NULL, role text NOT NULL DEFAULT 'member' CHECK(role IN ('owner','member')), totp_secret text NOT NULL, last_totp_step bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_owner ON users(role) WHERE role='owner';
CREATE TABLE sessions(token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), elevated_until timestamptz NOT NULL DEFAULT now()+interval '10 minutes');
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE rate_limits(key text PRIMARY KEY, count integer NOT NULL, reset_at timestamptz NOT NULL);
CREATE TABLE servers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, group_name text NOT NULL DEFAULT '默认分组', tags text[] NOT NULL DEFAULT '{}', notes text NOT NULL DEFAULT '', token_hash text UNIQUE, revoked boolean NOT NULL DEFAULT false, info jsonb NOT NULL DEFAULT '{}', last_seen timestamptz, latest jsonb, latest_at timestamptz, quota_bytes bigint, billing_day integer NOT NULL DEFAULT 1 CHECK(billing_day BETWEEN 1 AND 28), billing_interfaces text[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE enrollments(token_hash text PRIMARY KEY, server_id uuid NOT NULL REFERENCES servers ON DELETE CASCADE, expires_at timestamptz NOT NULL, used_at timestamptz);
CREATE TABLE metric_samples(server_id uuid NOT NULL REFERENCES servers ON DELETE CASCADE, boot_id uuid NOT NULL, seq bigint NOT NULL, collected_at timestamptz NOT NULL, data jsonb NOT NULL, PRIMARY KEY(server_id,boot_id,seq,collected_at)) PARTITION BY RANGE(collected_at);
CREATE INDEX metric_samples_lookup ON metric_samples(server_id,collected_at DESC);
CREATE TABLE metric_rollups(server_id uuid NOT NULL REFERENCES servers ON DELETE CASCADE, resolution integer NOT NULL CHECK(resolution IN(60,3600)), bucket timestamptz NOT NULL, count integer NOT NULL, data jsonb NOT NULL, PRIMARY KEY(server_id,resolution,bucket));
CREATE TABLE dirty_buckets(server_id uuid NOT NULL REFERENCES servers ON DELETE CASCADE, bucket timestamptz NOT NULL, PRIMARY KEY(server_id,bucket));
CREATE TABLE traffic_daily(server_id uuid NOT NULL REFERENCES servers ON DELETE CASCADE, day date NOT NULL, interface text NOT NULL, rx bigint NOT NULL DEFAULT 0, tx bigint NOT NULL DEFAULT 0, PRIMARY KEY(server_id,day,interface));
CREATE TABLE checks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), server_id uuid REFERENCES servers ON DELETE CASCADE, name text NOT NULL, kind text NOT NULL CHECK(kind IN('tcp','http','icmp','tls')), target text NOT NULL, interval_seconds integer NOT NULL DEFAULT 60 CHECK(interval_seconds BETWEEN 30 AND 3600), enabled boolean NOT NULL DEFAULT true, latest jsonb, last_run timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE check_results(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, check_id uuid NOT NULL REFERENCES checks ON DELETE CASCADE, checked_at timestamptz NOT NULL, data jsonb NOT NULL);
CREATE INDEX check_results_lookup ON check_results(check_id,checked_at DESC);
CREATE TABLE alert_rules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), server_id uuid REFERENCES servers ON DELETE CASCADE, name text NOT NULL, metric text NOT NULL CHECK(metric IN('offline','cpu','memory','disk','swap','check','certificate','traffic')), threshold double precision NOT NULL, recovery double precision NOT NULL, duration_seconds integer NOT NULL DEFAULT 60 CHECK(duration_seconds BETWEEN 0 AND 86400), enabled boolean NOT NULL DEFAULT true, muted_until timestamptz);
CREATE TABLE alerts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rule_id uuid NOT NULL REFERENCES alert_rules ON DELETE CASCADE, server_id uuid REFERENCES servers ON DELETE CASCADE, check_id uuid REFERENCES checks ON DELETE CASCADE, state text NOT NULL CHECK(state IN('pending','firing','resolved')), since timestamptz NOT NULL, value double precision NOT NULL, updated_at timestamptz NOT NULL, notified_at timestamptz, UNIQUE(rule_id,server_id), UNIQUE(rule_id,check_id), CHECK ((server_id IS NOT NULL AND check_id IS NULL) OR (server_id IS NULL AND check_id IS NOT NULL)));
CREATE TABLE channels(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, kind text NOT NULL CHECK(kind IN('webhook','telegram')), encrypted_config text NOT NULL, enabled boolean NOT NULL DEFAULT true);
CREATE TABLE notification_outbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), channel_id uuid NOT NULL REFERENCES channels ON DELETE CASCADE, payload jsonb NOT NULL, attempts integer NOT NULL DEFAULT 0, next_attempt timestamptz NOT NULL DEFAULT now(), delivered_at timestamptz, last_error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, user_id uuid REFERENCES users ON DELETE SET NULL, action text NOT NULL, resource_id text, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE terminal_tickets(token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, session_hash text NOT NULL REFERENCES sessions(token_hash) ON DELETE CASCADE, server_id uuid NOT NULL REFERENCES servers ON DELETE CASCADE, expires_at timestamptz NOT NULL);
CREATE TABLE terminal_sessions(id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, server_id uuid NOT NULL REFERENCES servers ON DELETE CASCADE, started_at timestamptz NOT NULL DEFAULT now(), ended_at timestamptz, reason text);
CREATE TABLE diagnostic_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), server_id uuid NOT NULL REFERENCES servers ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, kind text NOT NULL CHECK(kind IN('processes','services','logs')), unit text, state text NOT NULL DEFAULT 'queued' CHECK(state IN('queued','running','done','failed')), result text, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL DEFAULT now()+interval '30 seconds');
CREATE TABLE resource_grants(user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, resource_id uuid NOT NULL, resource_type text NOT NULL CHECK(resource_type='proxy_instance'), permission text NOT NULL CHECK(permission IN('view','use','manage')), PRIMARY KEY(user_id,resource_id,permission));
INSERT INTO alert_rules(name,metric,threshold,recovery,duration_seconds) VALUES ('服务器离线','offline',45,30,30),('CPU 持续过高','cpu',90,75,120),('内存不足','memory',90,80,120),('磁盘空间不足','disk',90,85,60),('网络检查失败','check',1,0,60),('证书即将到期','certificate',14,21,0),('周期流量接近配额','traffic',90,80,0);
